<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\{Position,Department}; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class PositionController extends Controller { public function index(){return view('admin.positions.index',['departments'=>Department::where('status','active')->orderBy('name')->get()]);} public function data(){return response()->json(['data'=>Position::with('department')->withCount('vacancies')->latest()->get()]);} public function show(Position $position){return response()->json($position);} public function store(Request $r){$v=$r->validate(['department_id'=>'required|exists:departments,id','name'=>['required','max:100',Rule::unique('positions')->where(fn($q)=>$q->where('department_id',$r->department_id))],'description'=>'nullable','status'=>'required|in:active,inactive']);Position::create($v);return response()->json(['message'=>'Position added successfully.']);} public function update(Request $r,Position $position){$v=$r->validate(['department_id'=>'required|exists:departments,id','name'=>['required','max:100',Rule::unique('positions')->where(fn($q)=>$q->where('department_id',$r->department_id))->ignore($position->id)],'description'=>'nullable','status'=>'required|in:active,inactive']);$position->update($v);return response()->json(['message'=>'Position updated successfully.']);} public function destroy(Position $position){if($position->vacancies()->exists())return response()->json(['message'=>'Cannot delete position with vacancies.'],422);$position->delete();return response()->json(['message'=>'Position deleted successfully.']);} }
